#include "optimizer_loop_internal.h"

#include "ir_helpers.h"
#include "optimizer_calls.h"

bool optimizer_loop_jumps_to(const IrBlock* block, IrBlockId target) {
  return block->terminator.type == IR_TERMINATOR_JUMP &&
         block->terminator.value.jump_target == target;
}

size_t optimizer_loop_edge_count(const IrFunction* fn, IrBlockId target) {
  size_t count = fn->entrypoint == target;

  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    const IrBlock* block = &fn->blocks.data[b];
    const IrBlockTerminator* term = &block->terminator;

    count += optimizer_loop_jumps_to(block, target);

    if (term->type == IR_TERMINATOR_CONDITIONAL) {
      count += term->value.conditional_target.true_target == target;
      count += term->value.conditional_target.false_target == target;
    }
  }

  return count;
}

size_t optimizer_loop_operands_of(IrInstruction* inst, IrOperand** operands) {
  switch (ir_get_instruction_class(inst)) {
    case IR_INST_CLASS_UNARY:
      operands[0] = &inst->operands.unary.operand;
      return 1;

    case IR_INST_CLASS_BINARY:
      operands[0] = &inst->operands.binary.left;
      operands[1] = &inst->operands.binary.right;
      return 2;
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Remove builtin functions from the IR altogether (they should now
    // be handled by lowering to allow for their optimalization, no?). Propagate
    // these changes to the relevant systems (codegen, optimizer)"
    // Changes: Traverse substring operands when cloning or inspecting loop
    // regions.
    case IR_INST_CLASS_TERNARY:
      for (size_t i = 0; i < 3; i++)
        operands[i] = &inst->operands.ternary[i];
      return 3;
    case IR_INST_CLASS_STORE:
      operands[0] = &inst->operands.store.source;
      return 1;

    default:
      return 0;
  }
}

bool optimizer_loop_direct_use(IrOperand operand, IrValueId value) {
  return operand.type == IR_OP_VALUE && operand.value.id == value;
}

unsigned optimizer_loop_instruction_uses(IrInstruction* inst, IrValueId value) {
  unsigned count = 0;

  if (inst->type == IR_INST_CALL) {
    for (size_t i = 0; i < inst->operands.call.arg_count; i++)
      count += optimizer_loop_direct_use(inst->operands.call.args[i], value);
  } else {
    IrOperand* operands[3];
    size_t n = optimizer_loop_operands_of(inst, operands);

    for (size_t i = 0; i < n; i++)
      count += optimizer_loop_direct_use(*operands[i], value);
  }

  return count;
}

size_t optimizer_loop_region_index(const RangeBody* body, IrBlockId block) {
  for (size_t i = 0; i < body->count; i++)
    if (body->blocks[i] == block)
      return i;

  return IR_INVALID_ID;
}

/**
 * @brief Collect the explicit successor block IDs from a terminator.
 *
 * @param term Block terminator to examine.
 * @param targets Output array for successor block IDs.
 * @return Number of successor IDs written.
 */
static size_t successors(const IrBlockTerminator* term, IrBlockId* targets) {
  switch (term->type) {
    case IR_TERMINATOR_JUMP:
      targets[0] = term->value.jump_target;
      return 1;

    case IR_TERMINATOR_CONDITIONAL:
      targets[0] = term->value.conditional_target.true_target;
      targets[1] = term->value.conditional_target.false_target;
      return 2;

    default:
      return 0;
  }
}

// Collect blocks belonging to one iteration and reject paths outside the
// supported region.
bool optimizer_loop_collect_range_body(const IrFunction* fn,
                                       RangeBody* body,
                                       IrBlockId pre,
                                       IrBlockId head,
                                       IrBlockId test,
                                       IrBlockId exit) {
  for (size_t i = 0; i < body->count; i++) {
    const IrBlock* block = &fn->blocks.data[body->blocks[i]];
    body->instructions += block->instructions.count;

    if (body->instructions > 16)
      return false;

    IrBlockId targets[2];
    size_t count = successors(&block->terminator, targets);

    for (size_t j = 0; j < count; j++) {
      IrBlockId target = targets[j];

      if (target == body->latch ||
          optimizer_loop_region_index(body, target) != IR_INVALID_ID)
        continue;

      if (target == pre || target == head || target == test || target == exit ||
          body->count == MAX_RANGE_BLOCKS)
        return false;

      body->blocks[body->count++] = target;
    }
  }

  for (size_t i = 0; i <= body->count; i++) {
    IrBlockId target = i == body->count ? body->latch : body->blocks[i];
    size_t internal = i == 0;

    for (size_t j = 0; j < body->count; j++) {
      IrBlockId targets[2];
      size_t count =
          successors(&fn->blocks.data[body->blocks[j]].terminator, targets);

      for (size_t k = 0; k < count; k++)
        internal += targets[k] == target;
    }

    if (internal != optimizer_loop_edge_count(fn, target))
      return false;
  }

  return true;
}

IrOperand* optimizer_loop_terminator_operand(IrBlockTerminator* term) {
  switch (term->type) {
    case IR_TERMINATOR_CONDITIONAL:
      return &term->value.conditional_target.condition;
    case IR_TERMINATOR_RETURN:
      return &term->value.return_value;
    case IR_TERMINATOR_EXIT:
      return &term->value.exit_code;
    default:
      return NULL;
  }
}

size_t optimizer_loop_region_uses(IrFunction* fn,
                                  const RangeBody* body,
                                  IrValueId value) {
  size_t uses = 0;
  for (size_t b = 0; b < body->count; b++) {
    IrBlock* block = &fn->blocks.data[body->blocks[b]];
    for (size_t i = 0; i < block->instructions.count; i++)
      uses +=
          optimizer_loop_instruction_uses(&block->instructions.data[i], value);

    IrOperand* operand = optimizer_loop_terminator_operand(&block->terminator);
    uses += operand && optimizer_loop_direct_use(*operand, value);
  }

  return uses;
}

void optimizer_loop_substitute_iteration(IrFunction* fn,
                                         const RangeBody* body,
                                         IrOperand* operand,
                                         IrValueId induction,
                                         IrStackSlotId slot,
                                         IrOperand current,
                                         size_t offset) {
  if (operand->type != IR_OP_VALUE)
    return;

  if (operand->value.id == induction) {
    *operand = current;
    return;
  }

  for (size_t b = 0; b < body->count; b++) {
    const IrInstructionArray* instructions =
        &fn->blocks.data[body->blocks[b]].instructions;

    for (size_t i = 0; i < instructions->count; i++) {
      const IrInstruction* definition = &instructions->data[i];

      if (definition->result != operand->value.id)
        continue;

      if (definition->type == IR_INST_LOAD &&
          definition->operands.load.source == slot)
        *operand = current;
      else
        operand->value.id += offset;

      return;
    }
  }
}

// Translate value IDs in the clone and replace the induction operand for this
// iteration.
void optimizer_loop_clone_iteration_block(Ctx* ctx,
                                          IrFunctionId fid,
                                          IrBlockId destination,
                                          IrBlockId source,
                                          const RangeBody* body,
                                          IrValueId induction,
                                          IrStackSlotId slot,
                                          IrOperand current,
                                          size_t offset) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  const IrInstructionArray* original = &fn->blocks.data[source].instructions;
  IrInstructionArray* target = &fn->blocks.data[destination].instructions;

  for (size_t i = 0; i < original->count; i++) {
    IrInstruction inst = original->data[i];

    if (inst.type == IR_INST_LOAD && inst.operands.load.source == slot)
      continue;

    optimizer_clone_instruction(ctx, fid, destination, inst, 0, 0, NULL, 0);
    IrInstruction* copy = &target->data[target->count - 1];

    if (copy->result != IR_INVALID_ID)
      copy->result += offset;

    IrOperand* operands[3];
    size_t count = optimizer_loop_operands_of(copy, operands);
    for (size_t a = 0; a < count; a++)
      optimizer_loop_substitute_iteration(fn, body, operands[a], induction,
                                          slot, current, offset);

    if (copy->type == IR_INST_CALL)
      for (size_t a = 0; a < copy->operands.call.arg_count; a++)
        optimizer_loop_substitute_iteration(fn, body,
                                            &copy->operands.call.args[a],
                                            induction, slot, current, offset);
  }
}

IrBlockId optimizer_loop_iteration_target(const RangeBody* body,
                                          IrBlockId first,
                                          IrBlockId target) {
  return target == body->latch
             ? first + body->count
             : first + optimizer_loop_region_index(body, target);
}
